-- ============================================================
-- 0043 — Curadoria dos textos-base da RNC: Elétrica (EL)
-- Gerado da curadoria multi-agente (draft + verificação normativa).
-- Um UPDATE por item: gravidade + fundamentação + risco + ação específicos.
-- Escrita restrita a super_admin (tabela de plataforma).
-- ============================================================

-- EL-01 (8 itens)
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando a profundidade de lançamento ou as separações entre linhas estiverem abaixo do mínimo de projeto, ou quando a ausência de fita de advertência expuser os cabos a escavações futuras.',
  texto_fundamentacao_normativa = 'As rotas e valas de linhas subterrâneas devem reproduzir o traçado, a profundidade de assentamento, o envelope de proteção, a sinalização por fita de advertência e as distâncias de separação definidos em projeto, condição verificável por levantamento da vala antes do reaterro. Aplicam-se a NBR 5410 (instalações elétricas de baixa tensão), que estabelece requisitos para linhas elétricas enterradas, e o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}, que fixa o perfil da vala e o envelopamento. O critério "Profundidade, envelope, fita de advertência e separações" integra o plano de inspeção da obra e constitui requisito verificável de aceitação da etapa.',
  texto_risco_consequencia = 'Vala executada fora da profundidade ou do envelope de projeto, ou sem fita de advertência, deixa os cabos sujeitos a esforços mecânicos, ingresso de água e danos por escavações posteriores, com risco de falha de isolação, interrupção do circuito e retrabalho de reabertura de vala já reaterrada. A permanência da condição mantém o trecho enterrado em desconformidade até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) reabrir e conferir o trecho, medindo profundidade, envelope e separações e confrontando com o projeto executivo aprovado; (ii) corrigir a geometria da vala, refazer o envelope de proteção e instalar a fita de advertência no nível especificado antes do reaterro definitivo; (iii) evidenciar a correção com registro fotográfico da vala aberta ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'EL-01' and item_numero = 1;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica se houver evidência de raio de curvatura inferior ao mínimo do fabricante em cabo já energizável ou de dano visível à capa/isolação decorrente da curva.',
  texto_fundamentacao_normativa = 'O raio de curvatura de cada cabo deve respeitar o valor mínimo estabelecido na folha de dados do fabricante, parâmetro que preserva a integridade dos condutores, da blindagem e da isolação durante o lançamento e a acomodação final. Na ausência de norma numérica que fixe universalmente esse valor, a fundamentação assenta-se na especificação do fabricante do cabo, nas boas práticas de instalação e no projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. O critério "Conforme fabricante do cabo" integra o plano de inspeção da obra e constitui requisito verificável de aceitação da etapa.',
  texto_risco_consequencia = 'Curvatura inferior ao mínimo especificado provoca deformação da isolação, ruptura de fios da blindagem e concentração de campo elétrico no ponto dobrado, condições que reduzem a vida útil do cabo e podem evoluir para falha dielétrica em operação. A permanência do raio inadequado mantém latente o ponto fragilizado até a correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) identificar os pontos de curva fora de especificação e comparar o raio executado com o mínimo indicado pelo fabricante; (ii) reacomodar o cabo ampliando o raio ou substituir o trecho danificado quando houver comprometimento da capa ou isolação; (iii) evidenciar a correção com registro fotográfico do trecho reacomodado ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'EL-01' and item_numero = 2;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando houver dano à isolação atribuível ao puxamento ou uso de meias/olhais inadequados em cabos de seção elevada ou trechos de grande comprimento.',
  texto_fundamentacao_normativa = 'O esforço de puxamento durante o lançamento deve ser limitado ao valor máximo admissível do cabo e aplicado por meias de puxamento ou olhais apropriados, de modo a não transmitir tração à isolação nem aos condutores. Na ausência de norma numérica específica, a fundamentação apoia-se no limite de tração informado pelo fabricante do cabo, nas boas práticas de lançamento (uso de roldanas, lubrificante e dinamômetro) e no projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. O critério "Sem danos à isolação; meias/olhais adequados" integra o plano de inspeção da obra e constitui requisito verificável de aceitação da etapa.',
  texto_risco_consequencia = 'Puxamento com esforço excessivo ou com dispositivos inadequados provoca estiramento do condutor, alongamento e microfissuras na isolação e afrouxamento da conexão nas extremidades, defeitos que podem não se manifestar de imediato e resultar em falha dielétrica sob carga. A permanência da condição mantém o cabo com dano potencialmente oculto até a verificação. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) inspecionar as extremidades e a capa dos cabos lançados sob suspeita de sobretração, verificando marcas de estiramento e integridade das meias/olhais; (ii) substituir o trecho quando confirmado dano e refazer o lançamento com controle de tração por dinamômetro, roldanas e lubrificante adequado; (iii) evidenciar a correção com registro fotográfico do dispositivo de puxamento e do cabo ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'EL-01' and item_numero = 3;
update public.rnc_textos_base set
  gravidade_sugerida = 'Menor — elevar a Maior quando a ausência ou troca de identificação impedir a correta correlação circuito-cabo em manobras, ensaios ou manutenção com risco de energização indevida.',
  texto_fundamentacao_normativa = 'Todos os condutores devem ser identificados em suas extremidades por anilhas ou etiquetas coerentes com a lista de cabos, assegurando a correspondência inequívoca entre o cabo físico, o circuito e o esquema elétrico. Aplicam-se a NBR 5410 (instalações elétricas de baixa tensão), que exige a identificação de circuitos e condutores, e a lista de cabos e o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. O critério "Anilhas/etiquetas conforme lista de cabos" integra o plano de inspeção da obra e constitui requisito verificável de aceitação da etapa.',
  texto_risco_consequencia = 'Extremidades sem identificação ou com anilhas trocadas dificultam a conferência de circuitos, aumentam o tempo de comissionamento e a probabilidade de erro de conexão ou de energização indevida durante manobras e manutenção, com risco à segurança da equipe e à continuidade operacional. A permanência da condição mantém a rastreabilidade elétrica comprometida até a correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) conferir cada extremidade contra a lista de cabos e o diagrama, mapeando os pontos sem identificação ou com marcação divergente; (ii) instalar ou corrigir anilhas e etiquetas duráveis e legíveis em ambas as extremidades, conforme a codificação de projeto; (iii) evidenciar a correção com registro fotográfico das extremidades identificadas ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'EL-01' and item_numero = 4;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando circuitos CC e CA compartilharem o mesmo compartimento sem barreira ou quando a proximidade com cabos de dados comprometer a segurança ou a integridade dos sinais críticos.',
  texto_fundamentacao_normativa = 'A segregação entre circuitos de corrente contínua, corrente alternada e cabos de dados deve observar as distâncias de separação e o bandejamento definidos em projeto, prevenindo interferência eletromagnética e propagação de faltas entre sistemas. Na ausência de valor numérico universal aplicável, a fundamentação apoia-se nas boas práticas de compatibilidade eletromagnética e de coexistência entre circuitos de potência e de sinal, na separação por leitos e eletrocalhas dedicados e no projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}, que fixa as distâncias e o bandejamento por sistema. O critério "Distâncias e bandejamento conforme projeto" integra o plano de inspeção da obra e constitui requisito verificável de aceitação da etapa.',
  texto_risco_consequencia = 'A ausência de segregação entre CC, CA e dados favorece acoplamento eletromagnético, ruído e erros em sinais de comunicação e supervisão, além de permitir que uma falta em um sistema afete os demais compartilhando o mesmo leito, com impacto na confiabilidade e na segurança da instalação. A permanência da condição mantém os sistemas mutuamente expostos até a correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) levantar os trechos em que as distâncias ou a segregação por bandeja não atendem ao projeto; (ii) reorganizar o encaminhamento restabelecendo as distâncias de separação e o bandejamento por sistema, com barreiras ou eletrocalhas segregadas onde exigido; (iii) evidenciar a correção com registro fotográfico do leito reorganizado ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'EL-01' and item_numero = 5;
update public.rnc_textos_base set
  gravidade_sugerida = 'Crítica — manter em Crítica por tratar-se de conexão CC em série sob corrente de arranjo; rebaixar a Maior apenas quando a amostragem confirmar crimpagem íntegra e o ponto for de baixa criticidade.',
  texto_fundamentacao_normativa = 'Os conectores CC do tipo MC4 devem ser crimpados com o alicate e a matriz do próprio fabricante, garantindo o contato metálico especificado e a estanqueidade do acoplamento, com verificação por amostragem representativa. Aplicam-se a NBR 16690 (instalações elétricas de arranjos fotovoltaicos), que trata das conexões e do cabeamento CC, as instruções do fabricante do conector e o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. O critério "MC4 com alicate do fabricante; amostragem inspecionada" integra o plano de inspeção da obra e constitui requisito verificável de aceitação da etapa.',
  texto_risco_consequencia = 'Crimpagem executada com ferramenta inadequada ou incompleta gera resistência de contato elevada, aquecimento localizado e perda de estanqueidade, condições que evoluem para arco elétrico em corrente contínua, degradação do conector e princípio de incêndio, além de perda de geração. A permanência da condição mantém pontos quentes latentes no arranjo até a correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) ampliar a amostragem de inspeção dos conectores executados, verificando ferramenta empregada, ausência de fios fora do barril e travamento do acoplamento; (ii) refazer com alicate e matriz do fabricante todos os conectores reprovados ou de procedência duvidosa, substituindo terminais danificados; (iii) evidenciar a correção com registro fotográfico da crimpagem e do ensaio de tração/acoplamento ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'EL-01' and item_numero = 6;
update public.rnc_textos_base set
  gravidade_sugerida = 'Crítica — manter em Crítica quando o valor de isolamento medido ficar abaixo do critério de aceitação; rebaixar a Observação apenas se a pendência for exclusivamente documental, com valores aprovados já registrados.',
  texto_fundamentacao_normativa = 'A resistência de isolamento de cada circuito deve ser medida após o lançamento, com megôhmetro na tensão de ensaio aplicável, e comparada ao valor mínimo de aceitação, com emissão de relatório por circuito. Aplica-se a NBR 5410 (instalações elétricas de baixa tensão), que prevê o ensaio de resistência de isolamento na verificação final; para os circuitos CC do arranjo, adotam-se as boas práticas de comissionamento e os critérios de tensão de ensaio e de valor mínimo de aceitação fixados no projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. O critério "Megger com valores conforme critério; relatório por circuito" integra o plano de inspeção da obra e constitui requisito verificável de aceitação da etapa.',
  texto_risco_consequencia = 'A ausência do ensaio ou valores de isolamento abaixo do critério indicam isolação danificada, umidade ou contaminação nas terminações, condições que expõem a instalação a fuga de corrente, choque elétrico e falha dielétrica ao energizar, comprometendo a liberação do circuito. A permanência da condição mantém o circuito sem comprovação de integridade dielétrica até novo ensaio aprovado. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) executar ou repetir a medição de resistência de isolamento por circuito com megôhmetro calibrado na tensão de ensaio aplicável, registrando os valores; (ii) para circuitos reprovados, investigar e sanar a causa (secagem, refazer terminações ou substituir trecho) e reensaiar até atingir o critério de aceitação; (iii) evidenciar a correção com registro fotográfico do ensaio e emissão do relatório por circuito ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'EL-01' and item_numero = 7;
update public.rnc_textos_base set
  gravidade_sugerida = 'Menor — elevar a Maior quando a falta de registro bobina × trecho impedir a rastreabilidade de lote em caso de recall do fabricante ou de investigação de falha em campo.',
  texto_fundamentacao_normativa = 'A rastreabilidade deve correlacionar cada bobina de cabo, com seu número de lote e certificado, ao trecho efetivamente instalado, permitindo reconstituir a origem do material em auditorias, garantias e investigações de falha. Na ausência de norma numérica que fixe o registro, a fundamentação apoia-se no plano da qualidade da obra, nas boas práticas de controle de materiais e certificados de ensaio de fábrica e no projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. O critério "Registro bobina × trecho instalado" integra o plano de inspeção da obra e constitui requisito verificável de aceitação da etapa.',
  texto_risco_consequencia = 'A ausência do registro bobina × trecho impede vincular o cabo instalado ao lote e ao certificado de origem, inviabilizando a atuação seletiva em caso de recall, não conformidade de fábrica ou falha localizada, o que pode exigir substituição de trechos além do necessário. A permanência da condição mantém a instalação sem rastreabilidade de material até a regularização documental. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) resgatar as etiquetas e certificados das bobinas utilizadas e reconstituir a associação com os trechos instalados a partir dos registros de lançamento; (ii) formalizar a planilha de rastreabilidade bobina × trecho e anexar os certificados de ensaio de fábrica ao dossiê da qualidade; (iii) evidenciar a correção com registro fotográfico das etiquetas de bobina e da planilha consolidada ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'EL-01' and item_numero = 8;

-- EL-02 (7 itens)
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando a insuficiência de profundidade ou a ausência do envelope de concreto exigido expuser os cabos de média tensão a esforços mecânicos externos ou a interferências com outras redes enterradas',
  texto_fundamentacao_normativa = 'O assentamento de cabos de média tensão em vala deve respeitar a profundidade mínima, o berço, o reaterro e o envelopamento (dutos e envelope de concreto quando exigido) definidos para a classe de tensão, protegendo o cabo contra danos mecânicos e sinalizando a rota. Aplicam-se a NBR 14039 (instalações elétricas de média tensão de 1,0 kV a 36,2 kV) e o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}, que fixam a geometria da vala, o tipo de proteção e as cotas de lançamento. O critério de aceitação — dutos e envelope de concreto conforme projeto — integra o plano de inspeção da obra e constitui requisito verificável antes do fechamento da vala.',
  texto_risco_consequencia = 'Cabos de MT lançados com profundidade insuficiente ou sem o envelope de concreto exigido ficam vulneráveis a esmagamento por tráfego, escavações futuras e recalques do solo, com risco de dano à isolação, falha em serviço, interrupção de fornecimento e exposição a partes energizadas de média tensão. A permanência da condição mantém a rede desprotegida e de difícil correção após o reaterro definitivo. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) reabrir e conferir topograficamente a profundidade, o berço e o recobrimento do trecho, confrontando com o projeto executivo aprovado; (ii) executar o envelopamento em dutos e o envelope de concreto nos trechos onde exigido, restabelecendo a proteção mecânica e a rota projetada antes do reaterro; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) da vala aberta com o cabo já protegido e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'EL-02' and item_numero = 1;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando o raio de curvatura adotado for inferior ao mínimo do fabricante ou houver tração/esforço de puxamento acima do admissível, com risco de dano interno já consumado à isolação',
  texto_fundamentacao_normativa = 'O lançamento do cabo de MT deve respeitar o raio de curvatura mínimo e os limites de esforço de tração (puxamento) e de compressão lateral estabelecidos pelo fabricante para o modelo de cabo empregado, preservando a integridade da isolação, das blindagens e da veia condutora. Na ausência de norma numérica aplicável a este parâmetro, a fundamentação apoia-se na especificação técnica do fabricante do cabo, nas boas práticas de instalação e no projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. O critério — conformidade com o fabricante — é requisito verificável de aceitação do lançamento.',
  texto_risco_consequencia = 'Curvas mais fechadas que o raio mínimo ou tração acima do limite do fabricante provocam danos internos, muitas vezes não visíveis, à isolação e às blindagens do cabo de MT, gerando pontos de descarga parcial que evoluem para falha prematura em operação, com interrupção e risco elétrico. A permanência da condição mantém latente um defeito que tende a se manifestar apenas sob tensão de serviço. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) verificar in loco os raios de curvatura executados e os registros de esforço de puxamento, confrontando-os com a especificação do fabricante e o projeto; (ii) refazer os trechos com curvatura ou tração fora do admissível, e submeter à avaliação a substituição do lance quando houver indício de dano, evitando reutilizar cabo comprometido; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) dos raios refeitos e anexar a folha de dados do fabricante utilizada como referência, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'EL-02' and item_numero = 2;
update public.rnc_textos_base set
  gravidade_sugerida = 'Crítica — terminações e emendas de MT executadas por profissional não certificado ou com kit incompatível com a classe de tensão constituem ponto de falha e risco elétrico grave; manter Crítica salvo comprovação documental plena de qualificação e adequação do kit',
  texto_fundamentacao_normativa = 'As terminações e emendas de cabos de média tensão devem ser executadas por profissional certificado para a atividade, empregando kit apropriado à classe de tensão do circuito, com controle de limpeza, cobertura semicondutora e distâncias de escoamento, sob pena de comprometer a região de maior solicitação dielétrica do sistema. Aplica-se a NR-10 (Segurança em Instalações e Serviços em Eletricidade), que exige trabalhador qualificado, habilitado e autorizado para serviços em eletricidade, além da NBR 14039 e das instruções do fabricante do kit e do projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. O critério — kit correto para a classe de tensão e registro fotográfico por fase — é requisito verificável de aceitação.',
  texto_risco_consequencia = 'Terminações e emendas mal executadas ou com kit incompatível com a classe de tensão concentram gradientes elétricos, favorecem descargas parciais, trilhamento e falha por perfuração da isolação, podendo resultar em curto-circuito, incêndio, danos a equipamentos e risco de acidente elétrico grave ao pessoal. A ausência de registro fotográfico por fase impede a rastreabilidade e a verificação da execução. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) comprovar a certificação do profissional executante e a compatibilidade do kit com a classe de tensão do circuito, retendo as evidências no dossiê da obra; (ii) refazer as terminações e emendas que não atendam ao kit correto ou ao procedimento do fabricante, garantindo limpeza, cobertura semicondutora e distâncias corretas; (iii) evidenciar a correção com registro fotográfico por fase ({{evidencia_foto_correcao}}) e anexar o certificado do profissional e a referência do kit, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'EL-02' and item_numero = 3;
update public.rnc_textos_base set
  gravidade_sugerida = 'Crítica — energização de circuito de MT sem ensaios concluídos e aprovados, ou com relatórios não assinados, é bloqueante; manter Crítica até apresentação de relatórios assinados dentro do critério de aceitação',
  texto_fundamentacao_normativa = 'A liberação do circuito de média tensão está condicionada à realização dos ensaios de comissionamento — resistência de isolamento e ensaio de tensão aplicada em VLF — com resultados dentro do critério de aceitação e relatórios assinados pelo responsável técnico, comprovando a integridade dielétrica antes da energização. Na ausência de valor numérico normativo universal para o critério de aceitação de VLF, a fundamentação apoia-se no critério do próprio item, na especificação do fabricante do cabo/acessórios, nas boas práticas de comissionamento e no projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}, observada a NBR 14039 quanto à verificação final da instalação. O critério — isolamento/VLF conforme aceitação e relatórios assinados — é requisito verificável e bloqueante.',
  texto_risco_consequencia = 'A energização sem ensaios aprovados, ou apoiada em relatórios não assinados, admite entrar em serviço um cabo com defeito de isolação não detectado, com risco de falha catastrófica na partida, danos a equipamentos, interrupção e exposição do pessoal a arco elétrico de média tensão. A falta de relatório assinado ainda inviabiliza a rastreabilidade e a responsabilização técnica do comissionamento. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) executar ou repetir os ensaios de resistência de isolamento e de tensão aplicada (VLF) conforme o critério de aceitação, com equipamento calibrado; (ii) reter no dossiê os relatórios de ensaio devidamente assinados pelo responsável técnico, mantendo o circuito desenergizado e bloqueado até a aprovação; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) da execução do ensaio e anexar os relatórios assinados, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'EL-02' and item_numero = 4;
update public.rnc_textos_base set
  gravidade_sugerida = 'Menor — elevar a Maior quando a ausência ou troca de identificação de fases e circuitos puder induzir manobra ou intervenção incorreta em instalação de média tensão',
  texto_fundamentacao_normativa = 'As fases e os circuitos de MT devem ser identificados de forma clara, durável e padronizada, reproduzindo o esquema de cores/legendas do projeto, para permitir operação, manobra e manutenção seguras e a correta correspondência entre extremidades. A identificação e a sinalização de circuitos são também requisitos de segurança contemplados pela NR-10 (Segurança em Instalações e Serviços em Eletricidade); complementa-se a fundamentação pelo padrão de identificação do projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}, e pelas boas práticas de instalação. O critério — padrão do projeto aplicado — é requisito verificável de aceitação.',
  texto_risco_consequencia = 'A falta de identificação, ou identificação divergente do padrão do projeto, induz a erros de manobra e de intervenção em circuitos de média tensão, aumentando o risco de energização indevida, curto-circuito e acidente elétrico ao pessoal de operação e manutenção, além de dificultar diagnósticos e ampliações futuras. A permanência da condição mantém a instalação sem rastreabilidade confiável de fases e circuitos. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) conferir a correspondência de fases e circuitos entre as extremidades e o esquema do projeto, corrigindo eventuais inversões; (ii) aplicar a identificação padronizada (cores, anilhas e placas) conforme o padrão do projeto, com materiais duráveis e legíveis nas caixas, terminações e pontos de acesso; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) da identificação aplicada nas extremidades, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'EL-02' and item_numero = 5;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando o afastamento insuficiente em cruzamentos ou paralelismos com outras redes (água, gás, comunicações, BT) criar risco de indução, interferência térmica ou dano recíproco',
  texto_fundamentacao_normativa = 'Os cruzamentos e paralelismos da rede de MT com outras utilidades enterradas devem respeitar as distâncias mínimas de segurança e as proteções de separação, evitando interferência térmica, eletromagnética e mecânica entre sistemas. Aplica-se a NBR 14039 (instalações elétricas de média tensão de 1,0 kV a 36,2 kV), expressamente indicada no critério do item, em conjunto com o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}, que define os afastamentos e as barreiras de separação. A conferência dos cruzamentos e paralelismos integra o plano de inspeção e constitui requisito verificável de aceitação.',
  texto_risco_consequencia = 'Distâncias de segurança inferiores às exigidas em cruzamentos e paralelismos expõem a rede de MT e as demais utilidades a aquecimento mútuo, indução, corrosão e a danos em intervenções futuras, podendo provocar falha da isolação, comprometimento das redes adjacentes e risco a terceiros que operem essas infraestruturas. A permanência da condição mantém o conflito de interferência ativo no subsolo. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) levantar os pontos de cruzamento e paralelismo e medir os afastamentos reais em relação às demais redes, confrontando com a NBR 14039 e o projeto; (ii) corrigir os trechos não conformes por reposicionamento, aprofundamento ou inserção de barreira/duto de separação, conforme o caso; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) dos afastamentos e das proteções aplicadas, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'EL-02' and item_numero = 6;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica em travessias de vias com tráfego de veículos pesados quando a proteção mecânica for inexistente ou insuficiente para as cargas atuantes',
  texto_fundamentacao_normativa = 'Nas travessias de vias, a rede de MT deve dispor de proteção mecânica reforçada (dutos/eletrodutos, envelope quando exigido e recobrimento adequado) e de sinalização que registre a presença do cabo, suportando as cargas do tráfego e prevenindo danos por escavações. Na ausência de índice numérico normativo específico para este parâmetro, a fundamentação apoia-se no critério do item (proteção mecânica e sinalização em cruzamentos de vias), na NBR 14039 quanto à proteção da instalação de MT e no projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. A conferência da proteção e da sinalização das travessias é requisito verificável de aceitação.',
  texto_risco_consequencia = 'Travessias de via sem proteção mecânica reforçada ou sem sinalização deixam o cabo de MT sujeito a esmagamento pelo tráfego e a rompimento em futuras intervenções na pista, com risco de dano à isolação, falha em serviço, interrupção do fornecimento e exposição de partes energizadas em local de circulação de veículos e pessoas. A permanência da condição mantém um ponto crítico da rota desprotegido. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) identificar as travessias de via e verificar a proteção mecânica (dutos/envelope) e o recobrimento executados frente às cargas de tráfego previstas; (ii) reforçar a proteção mecânica e implantar a sinalização de advertência (fita/tela de aviso e sinalização de superfície) nos cruzamentos, conforme projeto; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) da proteção e da sinalização instaladas na travessia, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'EL-02' and item_numero = 7;

-- EL-03 (6 itens)
update public.rnc_textos_base set
  gravidade_sugerida = 'Menor — elevar a Maior se a frente executar conexões de potência sem qualquer referência de torque disponível, pois nesse caso o aperto passa a ser arbitrado em campo',
  texto_fundamentacao_normativa = 'O aperto das conexões elétricas deve obedecer a valores de torque definidos por tipo de conexão, terminal e bitola, informação que precisa estar fisicamente acessível na frente de serviço para orientar e permitir a verificação da execução. Esses valores decorrem das especificações do fabricante dos conectores/terminais e do projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}, e são pré-requisito do controle de qualidade da etapa. A padronização do torque é boa prática consolidada de montagem elétrica para assegurar contato elétrico adequado e reprodutível. O critério "Valores por tipo de conexão definidos" integra o plano de inspeção e constitui requisito verificável de aceitação.',
  texto_risco_consequencia = 'A ausência do mapa de torque na frente permite que o aperto seja executado sem parâmetro, resultando em conexões sub ou sobretorqueadas, com aquecimento por mau contato, afrouxamento progressivo ou dano ao terminal, além de impedir a rastreabilidade e a conferência da inspeção. A permanência da condição mantém as conexões sem referência de aceitação até a disponibilização do documento. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) disponibilizar na frente de serviço o mapa de torque atualizado, com os valores por tipo de conexão, terminal e bitola extraídos das especificações do fabricante e do projeto executivo aprovado; (ii) vincular o mapa ao registro de execução, garantindo que cada conexão executada tenha o valor de referência correspondente; (iii) evidenciar a disponibilização e o uso do documento com registro fotográfico ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'EL-03' and item_numero = 1;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica se houver conexões de potência já apertadas com torquímetro sem certificado de calibração válido, exigindo reexecução do aperto',
  texto_fundamentacao_normativa = 'O torque só é confiável se o instrumento que o aplica estiver calibrado e com rastreabilidade metrológica comprovada por certificado válido, cujo número deve ser registrado no relatório para vincular o aperto executado ao equipamento utilizado. A exigência decorre da necessidade de garantir a exatidão da grandeza aplicada, conforme boas práticas de metrologia e controle de qualidade, e do projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}, que estabelece os valores a serem atingidos. A rastreabilidade do instrumento é pré-requisito para aceitar o aperto como controlado. O critério "Certificado válido; nº registrado no relatório" integra o plano de inspeção e é requisito verificável de aceitação.',
  texto_risco_consequencia = 'O uso de torquímetro descalibrado ou sem certificado válido invalida o controle do aperto: o valor indicado pode divergir do real, produzindo conexões fora da faixa especificada sem que o desvio seja detectado, com risco de aquecimento, falha de contato e comprometimento da rastreabilidade de toda a etapa. A permanência da condição mantém em dúvida a conformidade dos torques já aplicados. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) retirar de uso o instrumento sem certificado válido e disponibilizar torquímetro calibrado, com certificado dentro do prazo de validade; (ii) registrar no relatório o número do certificado e a identificação do instrumento, e reconferir/reexecutar os apertos realizados no período de dúvida; (iii) evidenciar a calibração vigente e o registro no relatório com cópia do certificado e registro fotográfico ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'EL-03' and item_numero = 2;
update public.rnc_textos_base set
  gravidade_sugerida = 'Menor — elevar a Maior quando a ausência de marcação impedir identificar quais conexões de potência já foram efetivamente torqueadas, gerando pontos não verificados',
  texto_fundamentacao_normativa = 'A marcação com caneta de torque (linha-testemunha) aplicada após o aperto em 100% das conexões de potência é o meio visual que evidencia que a conexão foi torqueada e permite detectar posteriormente eventual afrouxamento pelo desalinhamento da marca. Trata-se de boa prática consolidada de controle de conexões elétricas, complementar ao projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}, e ao registro de execução. A marcação assegura a rastreabilidade visual do aperto ponto a ponto. O critério "Caneta de torque em 100% das conexões de potência" integra o plano de inspeção e constitui requisito verificável de aceitação da etapa.',
  texto_risco_consequencia = 'Sem a marcação pós-torque nas conexões de potência perde-se a evidência visual de que o aperto foi executado e o indicador de afrouxamento futuro, dificultando a inspeção e o reaperto, e permitindo que conexões não torqueadas passem despercebidas, com risco de mau contato e aquecimento em operação. A permanência da condição mantém as conexões sem meio de verificação visual até a aplicação da marcação. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) aplicar a marcação com caneta de torque em 100% das conexões de potência imediatamente após o aperto no valor especificado, formando a linha-testemunha entre terminal, parafuso e barramento/base; (ii) inspecionar as conexões já executadas e completar a marcação onde estiver ausente, corrigindo o aperto quando a conferência indicar necessidade; (iii) evidenciar a marcação aplicada com registro fotográfico ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'EL-03' and item_numero = 3;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica se a crimpagem com matriz incorreta atingir condutores de potência ou circuitos de proteção, comprometendo a continuidade elétrica',
  texto_fundamentacao_normativa = 'A compressão do terminal deve ser feita com a combinação correta de terminal, bitola do cabo e matriz da ferramenta de crimpagem, pois é essa correspondência que garante a pressão adequada, a continuidade elétrica e a resistência mecânica da terminação; a conferência amostral confirma a conformidade do lote executado. A exigência decorre das especificações do fabricante do terminal e da ferramenta de crimpagem e do projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. A correspondência terminal-cabo-matriz é boa prática consolidada de terminação de condutores para assegurar contato elétrico e integridade mecânica. O critério "Terminal × cabo × matriz conferidos; inspeção amostral" integra o plano de inspeção e é requisito verificável de aceitação.',
  texto_risco_consequencia = 'Crimpagem com matriz incorreta gera compressão insuficiente ou excessiva do terminal, resultando em contato elétrico deficiente, aumento de resistência e aquecimento localizado, ou em fragilização mecânica do condutor, com risco de rompimento, falha da conexão e, em circuitos de potência, de sobreaquecimento e princípio de incêndio. A permanência da condição mantém terminações de confiabilidade duvidosa em serviço. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) conferir e corrigir a correspondência terminal × bitola do cabo × matriz, ajustando a ferramenta e a matriz aos valores especificados pelo fabricante; (ii) refazer as terminações executadas com matriz incorreta e ampliar a inspeção amostral para dimensionar a extensão do desvio no lote; (iii) evidenciar as crimpagens refeitas e a conferência com registro fotográfico ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'EL-03' and item_numero = 4;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando a conexão alumínio-cobre sem antioxidante integrar circuito de potência ou condutor de aterramento sujeito a corrente permanente',
  texto_fundamentacao_normativa = 'Nas conexões entre metais dissimilares, notadamente alumínio-cobre, deve ser aplicado composto antioxidante onde especificado, para inibir a oxidação e a corrosão galvânica na interface e preservar a continuidade elétrica ao longo da vida útil. A exigência decorre das especificações do fabricante do conector e do projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}, sendo boa prática consolidada para junções de alumínio. O tratamento antioxidante assegura contato elétrico durável na interface entre condutores de metais diferentes. O critério "Conexões alumínio-cobre tratadas" integra o plano de inspeção e constitui requisito verificável de aceitação.',
  texto_risco_consequencia = 'A omissão do antioxidante em conexões alumínio-cobre favorece a formação de camada de óxido e a corrosão galvânica na interface, elevando progressivamente a resistência de contato, o aquecimento e o afrouxamento, com risco de falha da conexão, interrupção do circuito e, em pontos de potência, de sobreaquecimento. A permanência da condição mantém a degradação da interface ativa até o tratamento das conexões. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) identificar as conexões alumínio-cobre especificadas e aplicar o composto antioxidante conforme orientação do fabricante, com limpeza prévia das superfícies de contato; (ii) refazer o aperto no torque especificado após a aplicação e verificar as demais conexões dissimilares da frente; (iii) evidenciar o tratamento aplicado com registro fotográfico ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'EL-03' and item_numero = 5;
update public.rnc_textos_base set
  gravidade_sugerida = 'Menor — elevar a Maior se a ausência do plano de reaperto pós-energização deixar sem controle conexões de potência sujeitas a acomodação térmica na comissionamento',
  texto_fundamentacao_normativa = 'As conexões apertadas tendem a acomodar-se sob os primeiros ciclos térmicos após a energização, razão pela qual deve haver plano de reaperto programado, registrado e articulado com a atividade de comissionamento (interface CM), definindo prazos, pontos e valores de reaperto. A exigência decorre das boas práticas de comissionamento e das recomendações do fabricante, complementadas pelo projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. O reaperto programado é boa prática consolidada para preservar a confiabilidade das conexões após a acomodação térmica. O critério "Plano de reaperto pós-energização (interface CM)" integra o plano de inspeção e é requisito verificável de aceitação da etapa.',
  texto_risco_consequencia = 'Sem o reaperto programado e registrado, as conexões que se acomodam após a energização permanecem afrouxadas, com aumento de resistência de contato, aquecimento e evolução para falha, sem que haja atividade formal prevista para detectar e corrigir a condição, além de romper a rastreabilidade com o comissionamento. A permanência da condição mantém o risco de afrouxamento não monitorado até a formalização do plano. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) elaborar e registrar o plano de reaperto pós-energização, definindo pontos, valores, prazos e responsáveis, em articulação com a equipe de comissionamento (interface CM); (ii) executar e registrar o reaperto nas conexões de potência conforme o plano, atualizando o histórico de cada ponto; (iii) evidenciar o plano formalizado e os reapertos realizados com registro fotográfico ({{evidencia_foto_correcao}}) e registro documental, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'EL-03' and item_numero = 6;

-- EL-04 (8 itens)
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando a seção do condutor ou a profundidade de enterramento estiverem abaixo do projeto a ponto de comprometer a equipotencialização geral ou a capacidade de escoamento de correntes de falta e de descarga atmosférica.',
  texto_fundamentacao_normativa = 'A malha de aterramento deve reproduzir a geometria, a profundidade de assentamento e a seção dos condutores definidas no projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}, pois delas dependem a resistência de aterramento de projeto, o controle de tensões de passo e de toque e o escoamento de correntes de falta e de origem atmosférica. Aplicam-se a NBR 5419 (proteção contra descargas atmosféricas, subsistema de aterramento) e a NBR 5410 (aterramento e equipotencialização de instalações elétricas). O critério "Profundidade, seção do condutor e geometria" integra o plano de inspeção da obra e constitui requisito verificável de aceitação desta etapa.',
  texto_risco_consequencia = 'Malha executada com condutor subdimensionado, geometria alterada ou profundidade insuficiente reduz a eficácia da dissipação de correntes, eleva as tensões de passo e de toque e degrada a resistência de aterramento, expondo pessoas a choque elétrico e equipamentos a sobretensões e danos. A permanência da condição mantém ativo o desvio no núcleo da proteção elétrica da instalação até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) confrontar o traçado, a profundidade e a seção dos condutores executados com o projeto executivo aprovado, mapeando os trechos divergentes antes do reaterro definitivo; (ii) corrigir a malha — substituindo condutores subdimensionados, reposicionando trechos e restabelecendo a profundidade de assentamento — de modo a reproduzir a geometria de projeto; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e croqui as-built do trecho, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'EL-04' and item_numero = 1;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando a solda apresentar falha de fusão, porosidade acentuada ou secção reduzida que comprometa a continuidade elétrica e mecânica da conexão do sistema de aterramento.',
  texto_fundamentacao_normativa = 'As conexões por solda exotérmica devem assegurar continuidade elétrica de baixa impedância e resistência mecânica permanente entre os elementos da malha, condição obtida com o molde correto para a bitola e a geometria da junta e com o cadinho/carga adequados, resultando em solda íntegra, sem porosidade, escória aprisionada ou falta de fusão. Aplica-se a NBR 5419 (conexões do subsistema de aterramento de SPDA), complementada pelas recomendações do fabricante do processo exotérmico e pelas boas práticas de execução. O critério "Molde correto; solda íntegra (amostragem visual)" integra o plano de inspeção e constitui requisito verificável de aceitação.',
  texto_risco_consequencia = 'Solda exotérmica executada com molde incorreto ou com defeitos de fusão gera conexão de alta impedância ou mecanicamente frágil, que pode romper-se sob solicitação térmica de uma corrente de falta ou de descarga, interrompendo a continuidade da malha e anulando a equipotencialização no ponto. A permanência da condição mantém um ponto latente de descontinuidade que só se manifesta sob evento de falta, quando a proteção é exigida. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) inspecionar visualmente as conexões da amostra e ampliar a amostragem sobre as juntas executadas com o mesmo molde/operador, identificando as soldas com porosidade, falta de fusão ou secção reduzida; (ii) refazer as conexões reprovadas com molde e carga corretos para a bitola, removendo a solda defeituosa e restabelecendo a junta íntegra; (iii) evidenciar a correção com registro fotográfico das novas soldas ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'EL-04' and item_numero = 2;
update public.rnc_textos_base set
  gravidade_sugerida = 'Menor — elevar a Maior quando a inacessibilidade ou a ausência de identificação das caixas e hastes impedir a medição periódica de resistência ou a manutenção do sistema de aterramento.',
  texto_fundamentacao_normativa = 'As hastes e as caixas de inspeção devem permanecer acessíveis e identificadas para viabilizar a medição periódica da resistência de aterramento e as intervenções de manutenção ao longo da vida útil da instalação, conforme previsto no projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. Aplicam-se a NBR 5419 (pontos de medição e inspeção do subsistema de aterramento) e a NR-10 (condições para inspeção e manutenção segura de instalações elétricas). O critério "Acessíveis e identificadas" integra o plano de inspeção e constitui requisito verificável de aceitação.',
  texto_risco_consequencia = 'Hastes e caixas de inspeção soterradas, obstruídas ou sem identificação inviabilizam a medição periódica e a manutenção do aterramento, mascarando eventual degradação da resistência ao longo do tempo e retardando intervenções corretivas, com risco à segurança de pessoas e à integridade dos equipamentos. A permanência da condição compromete a rastreabilidade e a verificabilidade do sistema de aterramento durante toda a operação. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) localizar e liberar as caixas de inspeção e as hastes, removendo obstruções e restabelecendo o acesso conforme o projeto; (ii) instalar ou recompor a identificação de cada ponto (tampa, plaqueta ou marcação normalizada), atualizando o cadastro de pontos de medição; (iii) evidenciar a correção com registro fotográfico dos pontos acessíveis e identificados ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'EL-04' and item_numero = 3;
update public.rnc_textos_base set
  gravidade_sugerida = 'Crítica — trata-se de equipotencialização de massas acessíveis (trackers, painéis, cercas e portões); manter como Crítica sempre que houver conexão ausente ou interrompida, rebaixando a Maior apenas em pendência documental de conexão já executada e íntegra.',
  texto_fundamentacao_normativa = 'Todas as massas metálicas expostas — estruturas de trackers, molduras de painéis, cercas e portões — devem estar efetivamente conectadas à malha de aterramento, garantindo a equipotencialização e um caminho de baixa impedância para correntes de falta, condição definida no projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. Aplicam-se a NBR 5410 (equipotencialização e aterramento de massas) e a NBR 5419 (interligação de elementos metálicos ao subsistema de aterramento), com a segurança de pessoas amparada pela NR-10. O critério "Trackers, painéis, cercas e portões equipotencializados" integra o plano de inspeção e constitui requisito verificável de aceitação.',
  texto_risco_consequencia = 'Estrutura ou fechamento metálico sem conexão à malha pode assumir potencial perigoso em condição de falta ou de descarga atmosférica, expondo operadores e terceiros que toquem trackers, painéis, cercas ou portões a choque elétrico com risco de morte, além de favorecer a circulação de correntes por caminhos indevidos. A permanência da condição mantém massas acessíveis eletricamente flutuantes em área de circulação de pessoas. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) percorrer trackers, fileiras de painéis, cercas e portões verificando a existência e a integridade de cada conexão de equipotencialização, listando os pontos ausentes ou interrompidos; (ii) executar ou refazer as conexões faltantes com condutor e conector adequados, assegurando continuidade à malha, inclusive nas cintas de aterramento de portões móveis; (iii) evidenciar a correção com registro fotográfico das conexões e, quando aplicável, medição de continuidade ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'EL-04' and item_numero = 4;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando a resistência medida superar o valor de projeto ou quando não houver registro do método e do instrumento, invalidando a comprovação de aceitação do aterramento.',
  texto_fundamentacao_normativa = 'A resistência de aterramento deve ser medida e comprovadamente igual ou inferior ao valor máximo estabelecido no projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}, com registro do método empregado (por exemplo, queda de potencial) e do instrumento utilizado, incluindo sua identificação e calibração. A verificação apoia-se na NBR 15749 (medição de resistência de aterramento e de potenciais na superfície do solo), com o desempenho do sistema referido à NBR 5419 e à NBR 5410. O critério "Valor ≤ projeto; método e instrumento registrados" integra o plano de inspeção e constitui requisito verificável de aceitação.',
  texto_risco_consequencia = 'Resistência de aterramento acima do valor de projeto — ou não comprovada por medição rastreável — significa que a instalação pode não escoar adequadamente correntes de falta e de descarga, elevando tensões de toque e de passo e reduzindo a eficácia da proteção, sem que a condição real esteja evidenciada. A permanência da condição mantém indeterminado o desempenho do aterramento até a realização de medição válida. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) realizar (ou repetir) a medição da resistência de aterramento por método reconhecido, com instrumento identificado e calibrado, registrando data, condições do solo e pontos medidos; (ii) caso o valor exceda o projeto, executar as melhorias necessárias (hastes adicionais, tratamento do solo ou ampliação da malha) e remedir até o atendimento; (iii) evidenciar a correção com o registro da medição conforme e fotografia do ensaio em campo ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'EL-04' and item_numero = 5;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando a ausência ou inconsistência da estratificação do solo comprometer o dimensionamento do aterramento da subestação e as tensões de passo e de toque de projeto.',
  texto_fundamentacao_normativa = 'Quando exigida, a resistividade do solo deve ser medida e estratificada para subsidiar o dimensionamento do sistema de aterramento da subestação e a verificação das tensões de passo e de toque, conforme o critério do item. Aplicam-se a NBR 15751 (sistemas de aterramento de subestações — requisitos), expressamente referida no critério, e a NBR 7117 (medição da resistividade e determinação da estratificação do solo), além do projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. O critério "Estratificação conforme NBR 15751 (SE)" integra o plano de inspeção e constitui requisito verificável de aceitação nas frentes que envolvem subestação.',
  texto_risco_consequencia = 'A ausência ou a inconsistência da medição de resistividade e da estratificação do solo retira a base técnica do dimensionamento do aterramento da subestação, podendo resultar em malha inadequada às tensões de passo e de toque admissíveis, com risco a operadores e à conformidade da SE. A permanência da condição mantém o dimensionamento sem lastro no comportamento real do solo. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) executar a medição da resistividade do solo pelo método de estratificação aplicável, cobrindo a área da subestação com espaçamentos adequados; (ii) processar os dados obtendo a estratificação do solo e confrontá-la com as premissas do projeto, revisando o dimensionamento do aterramento caso haja divergência relevante; (iii) evidenciar a correção com o relatório de resistividade/estratificação e registro fotográfico da campanha de medição ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'EL-04' and item_numero = 6;
update public.rnc_textos_base set
  gravidade_sugerida = 'Crítica — SPDA é sistema de proteção da vida e do patrimônio; manter como Crítica quando captores, descidas ou conexões de topo estiverem ausentes, incompletos ou fora de posição, rebaixando a Maior apenas em desvios geométricos menores sem perda de função.',
  texto_fundamentacao_normativa = 'O SPDA deve ser instalado reproduzindo o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}, quanto ao posicionamento e à quantidade de captores, ao roteamento e à quantidade de condutores de descida e à execução das conexões de topo, elementos que definem o volume de proteção e o caminho de escoamento da corrente de descarga até o aterramento. Aplica-se a NBR 5419 (proteção contra descargas atmosféricas), que estabelece os requisitos do sistema de captação, das descidas e das conexões. O critério "Captores, descidas e conexões de topo" integra o plano de inspeção e constitui requisito verificável de aceitação.',
  texto_risco_consequencia = 'Captação, descidas ou conexões de topo ausentes, incompletas ou fora de posição reduzem ou anulam o volume de proteção do SPDA, deixando estruturas e equipamentos expostos a impacto direto de descarga atmosférica, com risco de incêndio, danos aos equipamentos e à vida de pessoas presentes na instalação. A permanência da condição mantém a instalação desprotegida contra descargas até a conclusão e reinspeção do sistema. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) confrontar em campo captores, condutores de descida e conexões de topo com o projeto de SPDA, identificando elementos faltantes, mal posicionados ou com conexões incompletas; (ii) completar e corrigir a instalação — posicionando captores, restabelecendo descidas e refazendo conexões de topo — de modo a reconstituir o volume de proteção de projeto e a continuidade até o aterramento; (iii) evidenciar a correção com registro fotográfico dos captores, descidas e conexões executados ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'EL-04' and item_numero = 7;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando a instalação for energizada ou entregue sem o laudo de aterramento assinado por responsável técnico e sem a respectiva ART, por ausência da comprovação formal de conformidade do sistema.',
  texto_fundamentacao_normativa = 'A conformidade do sistema de aterramento deve ser formalizada em laudo técnico que consolide as medições e verificações realizadas, assinado por responsável técnico habilitado e amparado pela correspondente Anotação de Responsabilidade Técnica (ART), instrumento legal instituído pela Lei nº 6.496/1977 e vinculado ao registro no CREA. O laudo dá suporte documental ao atendimento da NBR 5419 e da NBR 5410 e ao projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. O critério "Assinado por responsável técnico com ART" integra o plano de inspeção e constitui requisito verificável de aceitação e de encerramento da etapa.',
  texto_risco_consequencia = 'A ausência do laudo de aterramento assinado por responsável técnico e da respectiva ART priva a obra da comprovação formal e da responsabilização técnica sobre a conformidade do sistema, fragilizando a rastreabilidade, o comissionamento e a defesa da instalação perante fiscalizações e eventuais sinistros. A permanência da condição mantém a etapa sem fechamento documental válido, ainda que a execução física esteja concluída. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) consolidar em laudo os resultados das medições de resistência e das verificações de execução do aterramento e do SPDA, com identificação dos instrumentos e métodos; (ii) obter a assinatura do responsável técnico habilitado e emitir/registrar a ART correspondente junto ao CREA, vinculando-a ao laudo; (iii) evidenciar a correção anexando o laudo assinado e a ART quitada, com registro fotográfico do documento protocolado ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'EL-04' and item_numero = 8;

-- EL-05 (7 itens)
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando o desnível ou a ausência do torque especificado comprometer a estabilidade mecânica do painel/inversor, o alinhamento de barramentos ou a integridade das conexões de força.',
  texto_fundamentacao_normativa = 'A fixação do painel/inversor/cubículo à sua base e o aperto dos elementos de fixação devem observar o nivelamento e os valores de torque estabelecidos no manual do fabricante e no projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. O nivelamento assegura o correto assentamento sobre a base/berço e o alinhamento de barramentos e acoplamentos, enquanto o torque especificado garante a fixação estrutural do conjunto e a manutenção do aperto sob vibração e ciclos térmicos. O critério "Nivelamento e torque de fixação" integra o plano de inspeção da obra e constitui requisito verificável de aceitação da montagem eletromecânica.',
  texto_risco_consequencia = 'Painel ou inversor mal nivelado ou com fixação sem o torque especificado fica sujeito a esforços mecânicos, vibração e deslocamentos que podem frouxar conexões, desalinhar barramentos e portas e comprometer a estabilidade do conjunto durante a operação, o transporte interno ou a movimentação de cargas próximas. A permanência da condição mantém o equipamento em situação de fixação inadequada, com propagação do afrouxamento às conexões elétricas, até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) reconferir o nivelamento do conjunto com nível de precisão e corrigir o calçamento/assentamento sobre a base conforme o manual do fabricante; (ii) reapertar todos os elementos de fixação aplicando o torque especificado com torquímetro aferido, registrando os valores obtidos em planilha; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e a planilha de torques, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'EL-05' and item_numero = 1;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica em ambientes externos, úmidos, com atmosfera agressiva ou poeira condutiva, ou quando o grau IP de projeto exigir proteção contra jatos d''água ou ingresso de partículas finas.',
  texto_fundamentacao_normativa = 'As entradas de cabos devem ser executadas com prensa-cabos ou sistema de selagem compatíveis, preservando o grau de proteção (IP) do invólucro definido em projeto para o local de instalação. Os graus de proteção proporcionados por invólucros de equipamentos elétricos são classificados conforme a NBR IEC 60529, e o grau IP requerido consta do projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}} e da especificação técnica do fornecimento. O critério "Prensa-cabos/selagem preservando grau IP" integra o plano de inspeção e constitui requisito verificável de aceitação da montagem.',
  texto_risco_consequencia = 'Entradas de cabos sem vedação adequada rebaixam o grau IP do invólucro e permitem o ingresso de água, poeira e insetos, favorecendo corrosão, trilhamento superficial, curtos-circuitos e degradação do isolamento dos componentes internos, com risco de indisponibilidade do equipamento, choque elétrico e princípio de incêndio. A permanência da condição mantém o interior do painel exposto ao meio agressivo até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) mapear todas as entradas com vedação deficiente, ausente ou com prensa-cabos de bitola/rosca incompatível; (ii) instalar prensa-cabos e elementos de selagem adequados ao diâmetro do cabo e ao grau IP de projeto, obturando aberturas não utilizadas com tampões cegos correspondentes; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'EL-05' and item_numero = 2;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando a ausência ou divergência de identificação impedir o seccionamento e o bloqueio do circuito correto para manobra ou intervenção.',
  texto_fundamentacao_normativa = 'Os circuitos, dispositivos de proteção e de comando devem ser identificados de forma inequívoca, com etiquetas legíveis e duráveis, e o diagrama atualizado deve estar afixado na porta do painel, em correspondência com o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. A NBR 5410 estabelece a identificação dos circuitos e componentes das instalações elétricas de baixa tensão, e a NR-10 requer a manutenção de esquemas unifilares e demais documentos da instalação atualizados. O critério "Etiquetas e diagrama atualizado na porta do painel" integra o plano de inspeção e constitui requisito verificável de aceitação.',
  texto_risco_consequencia = 'Identificação incompleta ou desatualizada induz a erro na operação e na manutenção, dificultando o seccionamento e o bloqueio do circuito correto e elevando o risco de manobra indevida, choque elétrico e arco elétrico durante intervenções em circuitos supostamente desenergizados. A permanência da condição mantém a instalação sem rastreabilidade confiável de seus circuitos até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) conferir circuito a circuito a correspondência entre etiquetas, dispositivos e diagrama, relacionando as divergências; (ii) confeccionar e aplicar etiquetas legíveis e duráveis e afixar o diagrama atualizado na porta do painel, alinhados ao projeto as built; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'EL-05' and item_numero = 3;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando os parâmetros divergentes envolverem ajustes de proteção, intertravamentos ou limites de operação cuja incorreção exponha pessoas e equipamentos a falha não protegida.',
  texto_fundamentacao_normativa = 'Os ajustes e configurações do equipamento — parâmetros de proteção, comando e operação acessados pela interface CM — devem reproduzir os valores definidos no projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}, no estudo de coordenação/seletividade e no manual do fabricante, com registro dos parâmetros iniciais efetivamente aplicados. O critério "Parâmetros iniciais registrados (interface CM)" integra o plano de inspeção e comissionamento e constitui requisito verificável de aceitação, assegurando rastreabilidade da configuração entregue e sua conformidade com o projeto.',
  texto_risco_consequencia = 'Parâmetros ajustados em desacordo com o projeto podem descoordenar as proteções, permitir operação fora dos limites seguros do equipamento e comprometer a seletividade, resultando em atuação indevida, ausência de proteção diante de uma falta e possível dano a inversores, painéis e à carga alimentada. A permanência da condição mantém o equipamento operando com configuração não validada até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) confrontar os parâmetros carregados na interface CM com os valores de projeto e do estudo de proteção, identificando cada divergência; (ii) reparametrizar o equipamento conforme o projeto e o manual do fabricante e registrar os valores finais em relatório de comissionamento; (iii) evidenciar a correção com registro fotográfico das telas de configuração e do relatório ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'EL-05' and item_numero = 4;
update public.rnc_textos_base set
  gravidade_sugerida = 'Menor — elevar a Maior, ou a Crítica, quando houver resíduos condutivos (limalha ou aparas metálicas) ou materiais inflamáveis no interior do equipamento na iminência da energização.',
  texto_fundamentacao_normativa = 'O interior de painéis, inversores e cubículos deve estar isento de resíduos de montagem — aparas de cabos, limalha metálica, poeira, ferramentas e materiais de embalagem — antes da energização, conforme boas práticas de comissionamento, o manual do fabricante e o plano de inspeção da obra vinculado ao projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. A limpeza interna é condição prévia de liberação para energização, verificada por inspeção visual, e o critério "Sem resíduos de montagem antes da energização" constitui requisito verificável de aceitação desta etapa.',
  texto_risco_consequencia = 'Resíduos de montagem no interior do painel, sobretudo partículas metálicas condutivas, podem provocar curtos-circuitos, arco elétrico e falha de isolamento no momento da energização, além de obstruir a ventilação e reter umidade, com risco de dano ao equipamento e de acidente ao pessoal presente na manobra de liberação. A permanência da condição mantém o risco latente até a efetiva remoção dos resíduos. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) inspecionar todo o interior do painel/cubículo, removendo aparas, limalha, poeira, ferramentas e embalagens; (ii) executar limpeza técnica adequada, por aspiração e meios que não danifiquem os componentes, confirmando a ausência de resíduos antes de liberar a energização; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'EL-05' and item_numero = 5;
update public.rnc_textos_base set
  gravidade_sugerida = 'Crítica — condição de segurança contra choque elétrico; rebaixar a Maior somente após restabelecida e comprovada a continuidade do aterramento dentro dos valores de referência.',
  texto_fundamentacao_normativa = 'A carcaça e as massas metálicas do equipamento devem estar conectadas ao sistema de aterramento de proteção, com continuidade elétrica comprovada por medição, garantindo o escoamento de correntes de falta e a atuação da proteção. A NBR 5410 estabelece o aterramento de proteção e a equipotencialização das massas em instalações de baixa tensão e, de forma correspondente, a NBR 14039 aplica-se às instalações em média tensão; a NR-10 trata das medidas de proteção contra choques elétricos. Aplica-se ainda o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. O critério "Continuidade conferida" integra o plano de inspeção e constitui requisito verificável de aceitação.',
  texto_risco_consequencia = 'Carcaça sem aterramento efetivo ou com continuidade deficiente pode assumir potencial perigoso em caso de falha de isolamento, expondo o pessoal a choque elétrico e podendo impedir a atuação das proteções por corrente de falta, com risco de acidente grave e de danos ao equipamento. A permanência da condição mantém as massas metálicas energizáveis sem referência de proteção até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) inspecionar o condutor de proteção e os pontos de conexão da carcaça ao barramento de aterramento, verificando bitola, aperto e ausência de corrosão; (ii) restabelecer ou reforçar a conexão e medir a continuidade/resistência de aterramento, confirmando valores dentro das referências de projeto e norma; (iii) evidenciar a correção com registro fotográfico e laudo de medição ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'EL-05' and item_numero = 6;
update public.rnc_textos_base set
  gravidade_sugerida = 'Menor — elevar a Maior quando os sobressalentes ou chaves faltantes forem itens críticos para a operação, a manobra segura ou a manutenção imediata do equipamento.',
  texto_fundamentacao_normativa = 'A entrega dos sobressalentes, ferramentas e chaves de operação/manobra deve corresponder integralmente à lista contratual e à especificação técnica do fornecimento, condição de recebimento do equipamento. O critério "Conforme lista do contrato" integra o plano de inspeção e o comissionamento, sendo requisito verificável de aceitação; a fundamentação decorre das obrigações contratuais e da documentação técnica vinculada ao projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}, não se aplicando norma técnica de produto específica a este item.',
  texto_risco_consequencia = 'A ausência dos sobressalentes e chaves previstos em contrato compromete a operação, a manobra segura e a pronta manutenção do equipamento, podendo prolongar indisponibilidades por falta de peças ou de meio de acionamento e gerar pendência contratual de fornecimento não sanada no recebimento. A permanência da condição mantém a obra sem os recursos de reposição e operação contratados até a efetiva regularização. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) conferir os itens recebidos contra a lista contratual de sobressalentes e chaves, relacionando faltas e divergências; (ii) providenciar a entrega dos itens pendentes com o respectivo termo de recebimento e guarda em local apropriado; (iii) evidenciar a correção com registro fotográfico dos itens entregues ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'EL-05' and item_numero = 7;

-- EL-06 (8 itens)
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando conexões sem torque ou fora de flecha estiverem em barramento sob tensão de operação ou alimentando cargas essenciais da subestação',
  texto_fundamentacao_normativa = 'A montagem de barramentos primários exige aperto controlado das conexões, controle das flechas dos condutores rígidos/flexíveis e continuidade elétrica das junções, condições que asseguram baixa resistência de contato e afastamentos mantidos entre fases. Aplica-se a NR-10, que trata da segurança em instalações e serviços em eletricidade, e o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}, complementados pelo mapa de torque e pelas instruções do fabricante do barramento, que definem os valores de aperto e as flechas admissíveis. O critério "Torque, flechas e conexões conferidos" integra o plano de inspeção e constitui requisito verificável de aceitação da etapa antes da energização.',
  texto_risco_consequencia = 'Conexão de barramento sem o torque especificado eleva a resistência de contato, gerando aquecimento localizado, oxidação e risco de falha de junta sob carga; flecha fora do projeto reduz os afastamentos entre fases e para a terra, aproximando a instalação da condição de arco elétrico e curto-circuito. A permanência da condição mantém ativo o risco de sobreaquecimento e de falha durante a operação da subestação. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) reapertar todas as conexões do barramento com torquímetro calibrado, aplicando os valores do mapa de torque e das instruções do fabricante, registrando os valores obtidos; (ii) reconferir e corrigir as flechas dos condutores, restabelecendo os afastamentos de projeto entre fases e para a terra; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e planilha de aperto assinada, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'EL-06' and item_numero = 1;
update public.rnc_textos_base set
  gravidade_sugerida = 'Crítica — manter Crítica sempre que a distância fase-fase ou fase-terra estiver abaixo do mínimo, pois compromete o isolamento; rebaixar a Maior somente em divergência documental sem redução física do afastamento',
  texto_fundamentacao_normativa = 'As distâncias elétricas de segurança (fase-fase e fase-terra) definem o isolamento no ar entre partes vivas e entre partes vivas e o aterramento, sendo determinantes para suportar as tensões de operação, de manobra e de impulso da subestação. Aplicam-se a NR-10, no que se refere às distâncias de segurança em instalações elétricas, a NBR 14039 para instalações de média tensão, quando esta for a classe de tensão do trecho, e o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}, que fixa os afastamentos mínimos. O critério "Fase-fase e fase-terra conforme projeto/norma" é requisito verificável e condição de aceitação prévia à energização.',
  texto_risco_consequencia = 'Distâncias elétricas inferiores às de projeto reduzem a rigidez dielétrica do ar entre partes energizadas, favorecendo descargas disruptivas, arco elétrico, curto-circuito e risco grave de acidente às equipes de operação e manutenção. A permanência da condição mantém a instalação em situação de isolamento insuficiente até a efetiva correção do afastamento. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) medir e confrontar as distâncias fase-fase e fase-terra do trecho com os afastamentos mínimos do projeto e da norma aplicável à classe de tensão; (ii) reposicionar isoladores, cadeias, condutores ou suportes de modo a restabelecer os afastamentos mínimos exigidos, sem tensão aplicada; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e croqui cotado das distâncias medidas, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'EL-06' and item_numero = 2;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando o desalinhamento de contatos ou o curso incorreto impedir a abertura/fechamento pleno da seccionadora ou a indicação confiável de posição, comprometendo o isolamento visível para manobra e manutenção',
  texto_fundamentacao_normativa = 'O ajuste das seccionadoras abrange o curso completo das lâminas, o alinhamento e a pressão dos contatos e a resposta dos comandos, garantindo abertura/fechamento pleno, contato elétrico adequado e isolamento visível seguro nas manobras. Aplicam-se a NR-10, quanto às manobras e ao seccionamento seguro, as instruções de montagem e ajuste do fabricante da seccionadora e o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. O critério "Curso, alinhamento de contatos e comandos" integra o plano de inspeção e é requisito verificável de aceitação da etapa.',
  texto_risco_consequencia = 'Seccionadora com contatos desalinhados ou curso incorreto pode não abrir/fechar completamente, resultando em contato parcial com aquecimento, falha de isolamento visível e risco de manobra sobre circuito indevidamente seccionado, expondo a equipe a choque e arco elétrico. A permanência da condição mantém ativo o risco de manobra insegura e de aquecimento dos contatos. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) reajustar o curso das lâminas e o alinhamento/pressão dos contatos conforme instruções do fabricante, verificando a abertura e o fechamento plenos; (ii) testar os comandos e a indicação de posição, corrigindo travamentos e intertravamentos conforme projeto; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e registro dos testes de manobra, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'EL-06' and item_numero = 3;
update public.rnc_textos_base set
  gravidade_sugerida = 'Crítica — manter Crítica quando houver pressão de SF6 fora da faixa, molas de acionamento não armadas/desreguladas ou sinalizações inoperantes, por afetarem diretamente a capacidade de interrupção; rebaixar a Maior apenas em pendência de sinalização auxiliar sem impacto no desempenho de interrupção',
  texto_fundamentacao_normativa = 'A instalação do disjuntor deve seguir as instruções do fabricante quanto à densidade/pressão do SF6 ou ao armazenamento de energia das molas, ao correto funcionamento dos comandos de abertura/fechamento e às sinalizações de estado, requisitos que asseguram a capacidade de interrupção de corrente de falta. Aplicam-se a NR-10, quanto à segurança de operação e manobra, o manual e os procedimentos de comissionamento do fabricante do disjuntor e o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. O critério "Pressão SF6/molas, comandos e sinalizações" é requisito verificável e condição de aceitação prévia à energização.',
  texto_risco_consequencia = 'Disjuntor com pressão de SF6 ou molas fora do especificado pode não interromper adequadamente a corrente de falta, permitindo que curtos-circuitos evoluam sem proteção efetiva; comandos ou sinalizações inoperantes levam a manobras cegas e à perda de seletividade, com risco de dano a equipamentos e de acidente. A permanência da condição mantém a subestação sem garantia de interrupção segura das faltas. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) verificar e restabelecer a pressão/densidade do SF6 ou a correta armação das molas conforme manual do fabricante, sanando eventuais vazamentos; (ii) testar os comandos de abertura/fechamento e todas as sinalizações de estado, corrigindo as falhas identificadas; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e relatório de comissionamento do disjuntor, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'EL-06' and item_numero = 4;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando o erro de polaridade, relação ou ligação estiver em TC/TP de circuito de proteção, por comprometer atuação e seletividade; manter Maior em circuitos exclusivos de medição/faturamento',
  texto_fundamentacao_normativa = 'A conferência de TCs e TPs abrange a polaridade dos enrolamentos, a relação de transformação e a fidelidade das ligações ao diagrama, condições essenciais para que os sistemas de proteção e medição recebam sinais corretos de corrente e tensão. Fundamenta-se no diagrama unifilar e nos diagramas de ligação do projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}, nas folhas de dados dos transformadores de instrumento e nas boas práticas de comissionamento; a NR-10 disciplina a execução segura dos ensaios em instalações elétricas. O critério "Polaridade, relação e ligações conforme diagrama" é requisito verificável de aceitação da etapa.',
  texto_risco_consequencia = 'Polaridade invertida, relação incorreta ou ligação divergente do diagrama nos TCs e TPs falseiam os sinais de proteção e medição, podendo provocar não atuação ou atuação indevida dos relés, perda de seletividade e faturamento/medição errôneos, além de risco de dano por falta não eliminada. A permanência da condição mantém a proteção e a medição operando sobre dados incorretos. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) reensaiar polaridade e relação de transformação e reconferir as ligações de cada TC e TP contra o diagrama de projeto, corrigindo inversões e desvios; (ii) revisar a continuidade dos secundários e o aterramento único conforme diagrama, evitando secundário de TC em aberto; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e relatório de ensaios dos transformadores de instrumento, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'EL-06' and item_numero = 5;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando houver trinca, lasca ou contaminação em isolador de coluna/pedestal que sustente parte viva ou equipamento, pela possibilidade de disrupção ou falha mecânica sob tensão',
  texto_fundamentacao_normativa = 'Os isoladores devem estar isentos de trincas, lascas e contaminação e submetidos a limpeza final antes da energização, condição que preserva a rigidez dielétrica da superfície e a integridade mecânica do apoio das partes energizadas. Fundamenta-se nas instruções do fabricante dos isoladores, nas boas práticas de comissionamento de subestações e na NR-10, quanto à segurança prévia à energização, além do projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. O critério "Sem trincas; limpeza final antes da energização" é requisito verificável e condição de aceitação da etapa.',
  texto_risco_consequencia = 'Isolador trincado ou contaminado apresenta caminho de fuga superficial e pode sofrer disrupção (flashover) ou ruptura mecânica sob tensão, provocando curto-circuito, queda de parte energizada e acidente grave. A permanência da condição mantém ativo o risco de falha de isolamento no momento da energização. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) inspecionar individualmente os isoladores e substituir os que apresentem trincas, lascas ou danos que comprometam o isolamento; (ii) executar a limpeza final das superfícies conforme recomendação do fabricante, removendo poeira, sais e resíduos de obra; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) dos isoladores íntegros e limpos, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'EL-06' and item_numero = 6;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando o item sem torque for conexão de corrente principal de alta tensão ou fixação estrutural de equipamento energizado, pelo risco de sobreaquecimento ou queda',
  texto_fundamentacao_normativa = 'As ferragens e conexões de alta tensão devem ser torqueadas segundo o mapa de torque, garantindo pressão de contato adequada nas junções de corrente e fixação mecânica segura de equipamentos e suportes. Fundamenta-se no mapa de torque de AT e nas instruções dos fabricantes dos conectores e ferragens, nas boas práticas de montagem eletromecânica e no projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}; a NR-10 disciplina a segurança da instalação. O critério "Mapa de torque de AT aplicado" integra o plano de inspeção e é requisito verificável de aceitação da etapa.',
  texto_risco_consequencia = 'Conexão de AT sem o torque do mapa apresenta alta resistência de contato e afrouxamento sob esforços térmicos e eletrodinâmicos, gerando sobreaquecimento, degradação da junta e risco de falha ou de queda de ferragens e equipamentos sobre a instalação. A permanência da condição mantém ativo o risco de ponto quente e de perda de fixação em serviço. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) reapertar as ferragens e conexões de AT com torquímetro calibrado segundo o mapa de torque, marcando as juntas conferidas com indicador de torque; (ii) verificar a integridade de conectores, arruelas e superfícies de contato, substituindo peças danificadas ou oxidadas; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e planilha de torque assinada, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'EL-06' and item_numero = 7;
update public.rnc_textos_base set
  gravidade_sugerida = 'Menor — elevar a Maior quando a ausência de TAG ou de sinalização de segurança impedir a identificação inequívoca de equipamento para manobra/bloqueio ou omitir advertência de risco elétrico em zona de acesso',
  texto_fundamentacao_normativa = 'As placas de identificação (TAGs) dos equipamentos e a sinalização de segurança asseguram a correta identificação para operação, manobra e bloqueio, além de advertir sobre o risco elétrico nas áreas da subestação. Aplicam-se a NR-10, quanto à identificação de circuitos e equipamentos e à sinalização de segurança em instalações elétricas, a NR-26, quanto à sinalização de segurança e ao uso de cores de advertência, e o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}, que define a codificação de TAGs. O critério "TAGs de equipamentos e sinalização de segurança" é requisito verificável de aceitação da etapa.',
  texto_risco_consequencia = 'A falta ou a incorreção de TAGs e de sinalização de segurança dificulta a identificação inequívoca dos equipamentos, favorecendo manobra ou intervenção em equipamento errado, falha de bloqueio/etiquetagem e exposição de pessoas ao risco elétrico por ausência de advertência. A permanência da condição mantém a instalação sem a identificação e a sinalização exigidas para operação segura. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) instalar/corrigir as placas de identificação (TAGs) de todos os equipamentos conforme a codificação do projeto; (ii) instalar a sinalização de segurança e as advertências de risco elétrico nos pontos exigidos, observando as cores e os padrões aplicáveis; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) das identificações e sinalizações instaladas, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'EL-06' and item_numero = 8;

-- EL-07 (6 itens)
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica se a subdimensionamento de condutor ou de proteção configurar risco de sobreaquecimento e incêndio no circuito de iluminação',
  texto_fundamentacao_normativa = 'Os circuitos de iluminação devem reproduzir a divisão, a proteção e a seção de condutores previstas no projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}, de modo que cada circuito seja adequadamente seccionado e protegido contra sobrecorrentes. Aplica-se a NBR 5410 (instalações elétricas de baixa tensão), que estabelece a coordenação entre a seção do condutor, a corrente de projeto e o dispositivo de proteção, bem como a divisão dos circuitos terminais. O critério "Divisão, proteção e seção de condutores" integra o plano de inspeção da obra e constitui requisito verificável de aceitação da etapa.',
  texto_risco_consequencia = 'Circuito de iluminação com divisão, seção de condutor ou proteção divergente do projeto pode operar em sobrecarga, provocando sobreaquecimento da isolação, atuação indevida ou ausência de atuação da proteção e risco de incêndio, além de indisponibilidade da iluminação em áreas atendidas pelo circuito. A permanência da condição mantém o circuito operando fora dos parâmetros de segurança dimensionados. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) confrontar a divisão dos circuitos, a seção dos condutores e os dispositivos de proteção instalados com o projeto executivo aprovado e a memória de cálculo; (ii) substituir condutores ou dispositivos de proteção não conformes e refazer o seccionamento dos circuitos conforme projeto, assegurando a coordenação condutor/proteção; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e, quando aplicável, ensaio de continuidade e medição, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'EL-07' and item_numero = 1;
update public.rnc_textos_base set
  gravidade_sugerida = 'Menor — elevar a Maior quando a falha de comando ou fotocélula comprometer o acionamento automático de iluminação de vias ou áreas críticas',
  texto_fundamentacao_normativa = 'Os comandos de iluminação e as fotocélulas devem estar operacionais e ter seu acionamento comprovado por testes registrados, conforme o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}} e as especificações do fabricante. Trata-se de requisito de comissionamento funcional: o critério "Testes de acionamento registrados" exige a demonstração prática de que cada dispositivo liga e desliga a iluminação nas condições previstas (manual e por sensor de luminosidade). Na ausência de norma específica aplicável ao ensaio destes dispositivos, a fundamentação apoia-se no critério do item, nas boas práticas de comissionamento eletroeletrônico e nas instruções de instalação do equipamento.',
  texto_risco_consequencia = 'Comandos ou fotocélulas inoperantes ou sem teste comprovado podem resultar em iluminação que não aciona ao anoitecer ou permanece ligada indevidamente, comprometendo a segurança de vias e ambientes e gerando consumo desnecessário de energia. A permanência da condição mantém indefinida a real funcionalidade do acionamento entregue. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) revisar ligações, ajustes e posicionamento dos comandos e fotocélulas conforme projeto e manual do fabricante; (ii) executar e registrar os testes de acionamento manual e automático de cada dispositivo, corrigindo os que não comutarem corretamente; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e o relatório dos testes de acionamento, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'EL-07' and item_numero = 2;
update public.rnc_textos_base set
  gravidade_sugerida = 'Crítica — manter como Crítica por tratar-se de sistema de segurança essencial à evacuação; rebaixar a Maior apenas se a não conformidade for pontual e não afetar rotas de fuga',
  texto_fundamentacao_normativa = 'A iluminação de emergência deve estar instalada com os pontos e a autonomia definidos no projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. Aplica-se a NBR 10898 (sistema de iluminação de emergência), que estabelece os requisitos de pontos de luz, sinalização de rotas de fuga e tempo mínimo de autonomia do sistema na falta de energia. O critério "Autonomia e pontos conforme projeto" integra o plano de inspeção e constitui requisito verificável de aceitação, por tratar-se de sistema de segurança destinado a garantir a evacuação segura das edificações.',
  texto_risco_consequencia = 'Iluminação de emergência ausente, com pontos incompletos ou autonomia insuficiente compromete a visibilidade das rotas de fuga em situação de falta de energia ou sinistro, elevando o risco de acidentes, pânico e falha na evacuação de pessoas. A permanência da condição mantém a edificação sem a proteção de segurança prevista em projeto. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) conferir a quantidade e a localização dos pontos de iluminação de emergência contra o projeto executivo aprovado; (ii) instalar ou reposicionar as unidades faltantes e ensaiar a autonomia do sistema por simulação de falta de energia, corrigindo baterias ou blocos que não atingirem o tempo mínimo de projeto; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e o relatório do ensaio de autonomia, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'EL-07' and item_numero = 3;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando a não conformidade no retificador ou no banco de baterias comprometer a alimentação CC de comando e proteção de sistemas essenciais',
  texto_fundamentacao_normativa = 'Os serviços auxiliares de corrente alternada e contínua — quadros QDCA e QDCC, retificador e banco de baterias — devem ser montados conforme o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}} e as especificações dos equipamentos. Para os quadros de baixa tensão em corrente alternada aplicam-se os requisitos de execução da NBR 5410 (instalações elétricas de baixa tensão). Para o retificador e o banco de baterias, na ausência de norma específica de que se tenha certeza aplicável a este item, a fundamentação apoia-se no critério do item, no projeto/especificação e nas boas práticas de montagem de serviços auxiliares CC, sendo "QDCA/QDCC, retificador e banco de baterias conforme projeto" requisito verificável de aceitação da etapa.',
  texto_risco_consequencia = 'Serviços auxiliares CA/CC montados em desacordo com o projeto podem resultar em alimentação de comando, proteção e sinalização indisponível ou instável, comprometendo a operação segura das instalações e a atuação de proteções que dependem da fonte CC, além de risco associado ao manuseio incorreto do banco de baterias. A permanência da condição mantém os sistemas essenciais sem a retaguarda de alimentação prevista. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) verificar a montagem, a interligação e a identificação dos quadros QDCA/QDCC, do retificador e do banco de baterias contra o projeto e as folhas de dados dos equipamentos; (ii) corrigir montagens, conexões e ajustes não conformes e ensaiar a tensão de flutuação e a autonomia do banco de baterias; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e os relatórios de ensaio dos serviços auxiliares, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'EL-07' and item_numero = 4;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando a ausência de dispositivo DR expuser usuários a contato indireto em áreas úmidas ou de uso geral',
  texto_fundamentacao_normativa = 'As tomadas de serviço devem ser distribuídas conforme o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}, protegidas por dispositivo diferencial-residual (DR) e devidamente identificadas. Aplica-se a NBR 5410 (instalações elétricas de baixa tensão), que exige a proteção adicional por dispositivo a corrente diferencial-residual de alta sensibilidade para circuitos de tomadas e prevê a identificação dos circuitos. O critério "Com DR e identificação" integra o plano de inspeção e constitui requisito verificável de aceitação, por assegurar a proteção das pessoas contra choques elétricos.',
  texto_risco_consequencia = 'Tomadas de serviço sem proteção por DR ou sem identificação expõem os usuários a choque elétrico por contato indireto em caso de falha de isolamento e dificultam a manobra e o bloqueio seguro dos circuitos para manutenção, aumentando o risco de acidentes de origem elétrica. A permanência da condição mantém os pontos de utilização sem a proteção adicional exigida. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) conferir a distribuição das tomadas de serviço contra o projeto e verificar a presença e a sensibilidade do dispositivo DR em cada circuito; (ii) instalar os dispositivos DR faltantes, corrigir a distribuição conforme projeto e aplicar a identificação dos circuitos e tomadas; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e o ensaio funcional do botão de teste do DR, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'EL-07' and item_numero = 5;
update public.rnc_textos_base set
  gravidade_sugerida = 'Crítica — manter como Crítica por envolver proteção contra descargas atmosféricas; rebaixar a Maior somente se a pendência for restrita a medição de continuidade sem comprometer o escoamento à terra',
  texto_fundamentacao_normativa = 'Os postes e torres de iluminação devem dispor de proteção contra descargas atmosféricas com aterramento individual conferido, conforme o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. Aplica-se a NBR 5419 (proteção contra descargas atmosféricas), que estabelece os requisitos do subsistema de aterramento e do escoamento das correntes de descarga, complementada pelos requisitos de aterramento da NBR 5410 (instalações elétricas de baixa tensão). O critério "Aterramento individual conferido" integra o plano de inspeção e constitui requisito verificável de aceitação da etapa.',
  texto_risco_consequencia = 'Postes ou torres de iluminação sem SPDA ou com aterramento individual não conferido ficam sujeitos a sobretensões e a potenciais perigosos em caso de descarga atmosférica, expondo pessoas a tensões de passo e de toque e podendo danificar equipamentos e a própria estrutura. A permanência da condição mantém as estruturas metálicas sem caminho seguro de escoamento à terra. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) verificar a existência e a integridade do aterramento individual de cada poste/torre contra o projeto de SPDA; (ii) executar ou corrigir as conexões de aterramento faltantes e medir a resistência de aterramento e a continuidade de cada ponto, adequando os valores fora do previsto; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e o relatório das medições de aterramento, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'EL-07' and item_numero = 6;

